import { createCommandBus, createExecutionContext, withUser } from "@zudojs/cqrs";
import { NotFoundError } from "@zudojs/errors";
import { createEventBus } from "@zudojs/events";

const events = createEventBus();
events.on("task.completed", (event) => console.log("event:", event.payload));
const rows = new Map([[1, { id: 1, userId: "ada", done: false }]]);
const commands = createCommandBus();

commands.register("CompleteTask", async (command, context) => {
  const userId = context?.userId;
  const task = rows.get(command.taskId);
  if (!task || task.userId !== userId) throw new NotFoundError(`Task ${command.taskId} not found`);
  task.done = true;
  await events.publishEvent({ type: "task.completed", payload: { taskId: task.id, userId } });
});

const base = createExecutionContext();
for (const user of ["linus", "ada"]) {
  try {
    await commands.execute({ type: "CompleteTask", taskId: 1 }, withUser(base, user));
    console.log(user, "done:", rows.get(1).done);
  } catch (error) {
    console.log(user, error.message);
  }
}

